const D = { density:.55, energy:.6, hue:30, speed:1, scale:1, x:.5, y:.5, shear:.5, fog:.6, style:'night_drive', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
if(!S.spr){ const R=64; const s=createGraphics(R*2,R*2); s.pixelDensity(1); s.noStroke();
  for(let r=R;r>0;r--){ const a=Math.pow(1-r/R,1.6)*255; s.fill(255,255,255,a*0.9); s.ellipse(R,R,r*2,r*2); }
  S.spr=s; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1);
  S.bead=[]; for(let k=0;k<260;k++) S.bead.push([fr(k*4+2),fr(k*4+3),fr(k*4+4),fr(k*4+5)]);
  S.lite=[]; for(let k=0;k<8;k++) S.lite.push([fr(k*5+50),fr(k*5+51),fr(k*5+52),0.4+fr(k*5+53)*0.9,fr(k*5+54)]);
}
const t=K.t*(0.6+P.speed*0.8);
const style=P.style;
// passing-light palette (h,s per light index via type)
const warm=[30,90], cool=[210,25], neon1=[315,85], neon2=[185,80];
function litColor(k){ if(style==='neon_city') return (k%2)?neon1:neon2; if(style==='noir') return [0,0]; if(style==='day_bus') return [210,10]; return (k%3===0)?cool:warm; }
const fogCol = style==='neon_city'?[300,30] : style==='noir'?[0,0] : style==='day_bus'?[210,12] : [220,25];

// --- fogged periphery (broad area element) ---
push(); blendMode(ADD); noStroke();
const fstr=(0.1+P.fog*0.6);
for(let ring=0;ring<3;ring++){ const rr=u*(0.9+ring*0.35);
  fill(fogCol[0], fogCol[1], style==='day_bus'?80:60, (style==='day_bus'?7:5)*fstr);
  ellipse(width*0.5, height*0.5, rr*2.2, rr*2.2);
}
// faint uniform veiling so the whole pane reads wet+lit
fill(fogCol[0], fogCol[1]*0.5, style==='day_bus'?85:55, 4*fstr + 2*K.intensity); rect(0,0,width,height);
blendMode(BLEND); pop();

// --- big passing lights, smeared horizontally (the key mover) ---
push(); blendMode(ADD); imageMode(CENTER); noStroke();
const litN=2+Math.round(P.density*6);
for(let k=0;k<litN;k++){ const l=S.lite[k];
  const dep=0.3+l[3];                       // depth -> speed & size
  const spd=(0.06+dep*0.12)*(1+P.energy);
  let lx=((l[0] + t*spd*(k%2?1:-1)) %1.3); if(lx<0)lx+=1.3; lx=(lx-0.15);
  const ly=(0.2+l[1]*0.6 + 0.03*Math.sin(t*0.4+k));
  const X=lx*width, Y=ly*height;
  const sz=u*(0.12+dep*0.22)*P.scale;
  const c=litColor(k);
  const br=(0.5+0.5*Math.sin(t*0.7+l[4]*6.28))*(0.6+P.energy*0.7);
  // elongated smear (motion blur of a passing light)
  tint(c[0], c[1], 100, Math.min(100, 22*br)); image(S.spr, X, Y, sz*2.6, sz*1.1);
  tint(c[0], c[1]*0.7, 100, Math.min(100, 60*br)); image(S.spr, X, Y, sz*1.0, sz*0.7);
}
imageMode(CORNER); blendMode(BLEND); pop();

// --- rain beads on the glass, sheared backward by vehicle motion ---
const nb=Math.round(70+P.density*170);
const shearA=(P.shear-0.5)*1.3;               // streak lean
push();
for(let k=0;k<nb;k++){ const b=S.bead[k];
  const runner = b[3] < (0.18+P.energy*0.25);  // some beads release and streak
  let by, bx;
  if(runner){
    const prog=(b[1] + t*0.14*(0.5+b[2]))%1;
    by=prog; bx=(b[0] + shearA*prog*0.35 + 0.02*Math.sin(t*2+k))%1; if(bx<0)bx+=1;
  } else {
    by=b[1] + 0.004*Math.sin(t*3.0+k);          // static bead, tiny vibration
    bx=b[0] + 0.003*Math.sin(t*2.3+k*1.7);
  }
  const X=bx*width, Y=by*height;
  const sz=(1.2+b[2]*4.0)*P.scale*(u/700+0.5);
  // bead = dark lens core + bright shoulder glint
  noStroke();
  fill(fogCol[0], 20, 22, 40); ellipse(X,Y,sz*(runner?1.0:1.4), sz*(runner?2.2:1.4));
  if(runner){ // clear trail
    stroke(fogCol[0], 12, 40, 12); strokeWeight(sz*0.5);
    line(X - shearA*sz*3, Y - sz*6, X, Y);
    noStroke();
  }
  fill(0,0,100, 55); ellipse(X - sz*0.28*(1+shearA), Y - sz*0.3, sz*0.4, sz*0.4);  // glint
}
pop();
